package com.gymmind.shared.async;
import org.springframework.stereotype.Component; import java.time.*; import java.util.*; import java.util.concurrent.atomic.AtomicLong;
@Component public class InMemoryPersistentJobQueue implements PersistentJobQueue { private final AtomicLong seq=new AtomicLong(); private final Map<Long,Mutable> jobs=new LinkedHashMap<>(); public synchronized Long enqueue(String t,Long tenant){if(t==null||t.isBlank()||tenant==null||tenant<=0)throw new IllegalArgumentException("invalid job");long id=seq.incrementAndGet();jobs.put(id,new Mutable(id,t,tenant));return id;} public synchronized Optional<PersistentJob> claimNext(Instant now,Duration lease){return jobs.values().stream().filter(j->j.status==JobStatus.PENDING&& !j.next.isAfter(now)).findFirst().map(j->{j.status=JobStatus.RUNNING;j.lease=now.plus(lease);return j.view();});} public synchronized void advance(Long id){getM(id).status=JobStatus.RUNNING;} public synchronized void retry(Long id,String e,Instant now){Mutable j=getM(id);j.attempts++;j.lastError=e;j.status=j.attempts>=5?JobStatus.FAILED:JobStatus.PENDING;j.next=now.plusSeconds(30L*(1L<<(j.attempts-1)));j.lease=null;} public synchronized void complete(Long id){getM(id).status=JobStatus.COMPLETED;getM(id).lease=null;} public synchronized void recoverExpired(Instant now){jobs.values().stream().filter(j->j.status==JobStatus.RUNNING&&j.lease!=null&&!j.lease.isAfter(now)).forEach(j->{j.status=JobStatus.PENDING;j.lease=null;});} public synchronized PersistentJob find(Long id){return getM(id).view();} private Mutable getM(Long id){Mutable j=jobs.get(id);if(j==null)throw new NoSuchElementException("job");return j;} private static final class Mutable{long id;String type;Long tenantId;JobStatus status=JobStatus.PENDING;int attempts;Instant next=Instant.EPOCH,lease;String lastError;Mutable(long i,String t,Long n){id=i;type=t;tenantId=n;}PersistentJob view(){return new PersistentJob(id,type,tenantId,status,attempts,next,lease,lastError);}} }

